[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ExePath,[string]$SmokeDataDir)
$ErrorActionPreference='Stop'; $exe=(Resolve-Path -LiteralPath $ExePath).Path; $frozenAppDir=Split-Path -Parent $exe
if([System.IO.Path]::GetExtension($exe) -ne '.exe'){throw "Frozen executable must have a .exe extension: $exe"}; if(-not(Test-Path -LiteralPath (Join-Path $frozenAppDir '_internal'))){throw 'Missing bundled runtime: _internal'}; foreach($required in @('examples','LICENSE')){if(-not(Test-Path -LiteralPath (Join-Path $frozenAppDir "_internal\$required"))){throw "Missing bundled resource: $required"}}
Write-Output "Frozen app directory: $frozenAppDir"; Write-Output "Frozen executable: $exe"
$oldSmoke, $oldLocalAppData = $env:AIVPV_SMOKE_TEST, $env:LOCALAPPDATA; try{$env:AIVPV_SMOKE_TEST='1'; if($SmokeDataDir){New-Item -ItemType Directory -Force -Path $SmokeDataDir|Out-Null; $env:LOCALAPPDATA=(Resolve-Path -LiteralPath $SmokeDataDir).Path}; $process=Start-Process -FilePath $exe -WorkingDirectory (Split-Path $exe) -WindowStyle Hidden -PassThru; if(-not $process.WaitForExit(10000)){Stop-Process -Id $process.Id -Force -ErrorAction SilentlyContinue; throw 'Frozen EXE smoke test timed out after 10 seconds.'}; if($process.ExitCode -ne 0){throw "Frozen EXE smoke test failed with code $($process.ExitCode)"}} finally {$env:AIVPV_SMOKE_TEST=$oldSmoke; $env:LOCALAPPDATA=$oldLocalAppData}; Write-Output 'EXE_SMOKE_RESULT = OK'
